/**
 * TASK: Complete the FrenchGreeter class below.
 *
 * The Greeter base class (provided above, do not change it) has:
 *   - a final greet() method: "Hello, " + name() + "!"
 *   - a name() method that returns "stranger"
 *
 * FrenchGreeter must override ONLY name() so that it returns "mon ami".
 * You may not (and cannot) override greet() -- it is final. After your
 * override, greet() should return "Hello, mon ami!" even when the object
 * is held in a Greeter variable.
 */
class Greeter {
    final String greet() {
        return "Hello, " + name() + "!";
    }

    String name() {
        return "stranger";
    }
}

public class FrenchGreeter extends Greeter {

    @Override
    String name() {
        // TODO: return "mon ami"
        return "";
    }
}

