public class FrenchGreeterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Greeter base = new Greeter();
        check("base name()", "stranger", base.name());
        check("base greet()", "Hello, stranger!", base.greet());

        FrenchGreeter fg = new FrenchGreeter();
        check("FrenchGreeter name()", "mon ami", fg.name());
        check("FrenchGreeter greet()", "Hello, mon ami!", fg.greet());

        Greeter ref = new FrenchGreeter();
        check("greet() through Greeter reference", "Hello, mon ami!", ref.greet());
        check("name() through Greeter reference", "mon ami", ref.name());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

